  .from(auditLog)
  .where(
    and(
      pageHistoryOf(contractorId, 'page_open'),
      gte(
        auditLog.at,
        sql`coalesce((select max(a.at) from audit_log a where a.contractor_id = ${contractorId} and a.entity = 'contractor_page' and a.action = 'page_on'), '-infinity'::timestamptz)`,
